import{z as p,x as B,o as t,c as d,q as l,j as i,D as e,d as r,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"类型反馈与推测","description":"","frontmatter":{"title":"类型反馈与推测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/type-feedback.md","filePath":"cs/type-feedback.md","lastUpdated":1791063341000}'),A={name:"cs/type-feedback.md"};function c(C,a,m,f,h,D){const o=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="类型反馈与推测" tabindex="-1">类型反馈与推测 <a class="header-anchor" href="#类型反馈与推测" aria-label="Permalink to &quot;类型反馈与推测&quot;">​</a></h1><div class="epigraph"><p>解释器或 IC 记录操作数见到的类型（或范围），JIT 按最常见类型特化代码，其它类型走去优化。反馈是轮廓在类型上的投影。</p><footer>—— 据 Hölzle and Ungar；Gal et al. 类型特化；对照[PGO](/cs/pgo) 与[渐进类型](/cs/gradual-typing) 整理</footer></div><p>上一课<a href="/cs/deoptimization">去优化</a> 提供失败通道。缺口是<strong>投机依据</strong>：类型反馈。<code>+</code> 在 JS 见过的都是 int，则发整数加，溢出或对象则 deopt。本课钉剖析数据结构，分层编译下一课用同一反馈升层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态 HM 在动态语言上没有。运行时：每个字节码或调用点一个 profile（位图、类型链）。JIT 读 profile 生成守卫。缺口是<strong>收集与消费</strong>，不是 deopt 帧格式。</p><p>与渐进：静态注解是程序员；反馈是机器观察。可同时存在。</p><h3 id="反馈不是证明" tabindex="-1">反馈不是证明 <a class="header-anchor" href="#反馈不是证明" aria-label="Permalink to &quot;反馈不是证明&quot;">​</a></h3><p>罕见类型没见到 ≠ 不会出现。必须守卫。不要删 deopt 路径。</p><p><span class="marginnote">「类型反馈」就是 JIT 在运行时偷记「这个加号见到的操作数都是什么类型」，再照这份记录生成只处理常见情况的快代码。它不是预言，是投票统计——所以要守卫兜底。</span></p><p><span class="marginnote">Self/HotSpot 类型 profile。V8 FeedbackVector。本课与 PGO 对照：一个在线、一个离线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>解释器更新计数（要廉价：饱和计数器）。编译：若单类型占 99% 则特化。Megamorphic 放弃。再编译：profile 变了则作废代码。</p>',12)),(t(),i(n,null,{default:e(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20INT%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%20--%3E%20FB%5B%22%E7%B1%BB%E5%9E%8B%20%2F%20%E5%80%BC%E5%8F%8D%E9%A6%88%22%5D%0A%20%20FB%20--%3E%20JIT%5B%22%E7%89%B9%E5%8C%96%E7%BC%96%E8%AF%91%22%5D%0A%20%20JIT%20--%3E%20GRD%5B%22%E5%AE%88%E5%8D%AB%22%5D%0A%20%20GRD%20--%3E%20DEOPT%5B%22%E5%A4%B1%E8%B4%A5%E5%8E%BB%E4%BC%98%E5%8C%96%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"与值范围：反馈可含常见立即数，用于推测常量。与 IC：IC 状态本身是反馈。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"一个调用点是怎么「烂掉」又怎么救回来的——问题不在类型多，而在都挤在同一个调用点上：",-1)),(t(),i(n,null,{default:e(()=>[s(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20CS%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E8%B0%83%E7%94%A8%E7%82%B9%22%5D%20--%3E%20T1%5B%22%E7%AC%AC%E4%B8%80%E5%9E%8B%20int%22%5D%0A%20%20CS%20--%3E%20T2%5B%22%E7%AC%AC%E4%BA%8C%E5%9E%8B%20double%22%5D%0A%20%20CS%20--%3E%20T3%5B%22%E6%9B%B4%E5%A4%9A%E7%B1%BB%E5%9E%8B%E4%B8%8D%E6%96%AD%E5%8A%A0%E5%85%A5%22%5D%0A%20%20T3%20--%3E%20MEGA%5B%22%E5%8F%98%E6%88%90%20megamorphic%22%5D%0A%20%20MEGA%20--%3E%20SLOW%5B%22%E6%94%BE%E5%BC%83%E7%89%B9%E5%8C%96%EF%BC%8C%E8%B5%B0%E6%85%A2%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SLOW%20--%3E%20CLONE%5B%22%E5%88%86%E8%A3%82%E8%B0%83%E7%94%A8%E7%82%B9%EF%BC%9A%E5%85%8B%E9%9A%86%E6%96%B9%E6%B3%95%22%5D%0A%20%20CLONE%20--%3E%20S1%5B%22%E5%89%AF%E6%9C%AC%E5%8F%AA%E5%96%82%20int%EF%BC%8C%E6%81%A2%E5%A4%8D%E7%89%B9%E5%8C%96%22%5D%0A%20%20CLONE%20--%3E%20S2%5B%22%E6%AE%8B%E7%95%99%E7%B1%BB%E5%9E%8B%E5%8D%95%E7%8B%AC%E4%B8%80%E4%BB%BD%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>多线程：profile 更新竞态可接受近似。不要为精确用全局锁。污染：一个调用点见过太多类型则永远慢——可分裂调用点（克隆方法）。</p><p>与<a href="/cs/sccp">SCCP</a>：静态常量 vs 动态常见值，后者必须检查。</p><p><span class="marginnote">数字实例：profile 计数通常用一个字节做饱和计数器，数到 255 就封顶不再加；只有单类型占比 \\(\\gt 99\\%\\) 时才敢发整数加，剩下那一点点留守卫——省的是检查开销，保的是偶发字符串类型不至于打崩进程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写分层阈值数字。后课默认：动态语言 JIT 吃类型反馈。下一课分层编译：解释器 → C1 → C2。</p><p>也不把反馈当推荐系统。</p><p><span class="marginnote">常见误区：初学者容易把类型反馈当成静态类型系统用——「编译过就安全」。实际上它只是「到目前为止的观察」，任何一次新类型出现都靠 deopt 兜底，而不是编译期保证；删掉去优化路径等于拆掉刹车。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型反馈：在线轮廓驱动特化。</li><li>必须保留去优化；反馈不是类型系统。</li><li>IC 是调用点上的反馈。</li><li>出处：Hölzle and Ungar；Gal et al.；对照 PGO。</li></ul>',9))])}const _=p(A,[["render",c]]);export{T as __pageData,_ as default};
